<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$type=(string)($_POST['type']??'');$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');$tables=['photo'=>['listing_photos','approved','rejected'],'guide'=>['guides','published','rejected'],'question'=>['questions','published','rejected'],'answer'=>['answers','published','rejected'],'recommendation'=>['recommendations','published','rejected']];
 if(isset($tables[$type])&&$id&&in_array($status,[$tables[$type][1],$tables[$type][2]],true)){[$table]=$tables[$type];db()->prepare('UPDATE '.$table.' SET status=:s WHERE id=:id')->execute([':s'=>$status,':id'=>$id]);flash('success',ucfirst($type).' moderation saved.');}
 elseif($type==='report'&&$id&&in_array($status,['reviewed','dismissed'],true)){db()->prepare('UPDATE content_reports SET status=:s WHERE id=:id')->execute([':s'=>$status,':id'=>$id]);flash('success','Report status updated.');}
 redirect(app_path('admin/insights.php'));
}
$reports=db()->query("SELECT r.*,u.name reporter FROM content_reports r LEFT JOIN users u ON u.id=r.reporter_id ORDER BY CASE r.status WHEN 'open' THEN 0 ELSE 1 END,r.created_at DESC LIMIT 100")->fetchAll();
$photos=db()->query("SELECT p.*,l.name listing_name,u.name contributor FROM listing_photos p JOIN listings l ON l.id=p.listing_id LEFT JOIN users u ON u.id=p.user_id WHERE p.status='pending' ORDER BY p.created_at ASC LIMIT 100")->fetchAll();
$guides=db()->query("SELECT g.*,u.name creator FROM guides g JOIN users u ON u.id=g.user_id WHERE g.status='pending' ORDER BY g.created_at ASC LIMIT 100")->fetchAll();
$questions=db()->query("SELECT q.*,l.name listing_name,u.name asker FROM questions q JOIN listings l ON l.id=q.listing_id JOIN users u ON u.id=q.user_id WHERE q.status='pending' ORDER BY q.created_at ASC LIMIT 100")->fetchAll();
$answers=db()->query("SELECT a.*,q.title question_title,u.name contributor FROM answers a JOIN questions q ON q.id=a.question_id JOIN users u ON u.id=a.user_id WHERE a.status='pending' ORDER BY a.created_at ASC LIMIT 100")->fetchAll();
$recommendations=db()->query("SELECT r.*,l.name listing_name,u.name contributor FROM recommendations r JOIN listings l ON l.id=r.listing_id JOIN users u ON u.id=r.user_id WHERE r.status='pending' ORDER BY r.created_at ASC LIMIT 100")->fetchAll();
$all=db()->query("SELECT id,name,city,location FROM listings WHERE status='published' ORDER BY name LIMIT 1000")->fetchAll();$duplicates=[];for($i=0;$i<count($all);$i++){for($j=$i+1;$j<count($all);$j++){if(strtolower(trim($all[$i]['city']?:$all[$i]['location']))!==strtolower(trim($all[$j]['city']?:$all[$j]['location'])))continue;$a=preg_replace('/[^a-z0-9]/','',strtolower($all[$i]['name']));$b=preg_replace('/[^a-z0-9]/','',strtolower($all[$j]['name']));if($a===''||$b==='')continue;$ratio=1-(levenshtein($a,$b)/max(strlen($a),strlen($b)));if($ratio>=0.78)$duplicates[]=['a'=>$all[$i],'b'=>$all[$j],'score'=>(int)round($ratio*100)];}}
usort($duplicates,fn($a,$b)=>$b['score']<=>$a['score']);$duplicates=array_slice($duplicates,0,25);
$reviews=db()->query("SELECT rating,comment FROM reviews WHERE status='approved' ORDER BY created_at DESC LIMIT 500")->fetchAll();$positive=['friendly','helpful','clean','great','excellent','good','fresh','quick','professional','comfortable','quality','recommend','love','best','polite'];$negative=['slow','rude','dirty','poor','expensive','late','broken','bad','worse','unhelpful','crowded','wait','issue','problem'];$signals=['positive'=>[],'negative'=>[]];foreach($reviews as $r){$text=strtolower($r['comment']);$bucket=(int)$r['rating']>=4?'positive':((int)$r['rating']<=2?'negative':'neutral');if($bucket==='neutral')continue;foreach($bucket==='positive'?$positive:$negative as $word){if(preg_match('/\b'.preg_quote($word,'/').'\b/',$text))$signals[$bucket][$word]=($signals[$bucket][$word]??0)+1;}}arsort($signals['positive']);arsort($signals['negative']);
$adminTitle='3.0 intelligence & moderation';include __DIR__.'/_header.php';
?>
<div class="stats-grid"><article class="stat-card"><span>Reports open</span><strong><?= count(array_filter($reports,fn($r)=>$r['status']==='open')) ?></strong><small>Community accuracy queue</small></article><article class="stat-card"><span>Photos pending</span><strong><?= count($photos) ?></strong><small>User-submitted gallery content</small></article><article class="stat-card"><span>Community posts pending</span><strong><?= count($guides)+count($questions)+count($answers)+count($recommendations) ?></strong><small>Guides, Q&A and recommendations</small></article><article class="stat-card"><span>Possible duplicates</span><strong><?= count($duplicates) ?></strong><small>Suggestions only · no auto-merge</small></article></div>
<section class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">DATA QUALITY ASSISTANT</span><h2>Potential duplicate businesses</h2><p class="form-footnote">Name similarity is heuristic. Review both records manually before changing or removing anything.</p></div></div><?php if($duplicates): ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Listing A</th><th>Listing B</th><th>Similarity</th></tr></thead><tbody><?php foreach($duplicates as $d): ?><tr><td><strong><?= h($d['a']['name']) ?></strong><small><?= h($d['a']['city']?:$d['a']['location']) ?></small><a href="<?= app_path('admin/listing-form.php?id='.(int)$d['a']['id']) ?>">Review A</a></td><td><strong><?= h($d['b']['name']) ?></strong><small><?= h($d['b']['city']?:$d['b']['location']) ?></small><a href="<?= app_path('admin/listing-form.php?id='.(int)$d['b']['id']) ?>">Review B</a></td><td><?= (int)$d['score'] ?>%</td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="empty-admin">No likely duplicates detected.</p><?php endif; ?></section>
<section class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">REVIEW INTELLIGENCE</span><h2>Common feedback signals</h2><p class="form-footnote">Rule-based keyword counts from up to 500 approved reviews. This is not an AI-generated sentiment verdict.</p></div></div><div class="lg3-insight-columns"><div><h3>Positive mentions</h3><?php foreach(array_slice($signals['positive'],0,10,true) as $w=>$n): ?><div class="lg3-signal"><span><?= h($w) ?></span><strong><?= (int)$n ?></strong></div><?php endforeach; ?><?php if(!$signals['positive']): ?><p class="muted">No matching terms.</p><?php endif; ?></div><div><h3>Improvement mentions</h3><?php foreach(array_slice($signals['negative'],0,10,true) as $w=>$n): ?><div class="lg3-signal"><span><?= h($w) ?></span><strong><?= (int)$n ?></strong></div><?php endforeach; ?><?php if(!$signals['negative']): ?><p class="muted">No matching terms.</p><?php endif; ?></div></div></section>
<?php foreach([['photos','photo','Community photo submissions',$photos],['guides','guide','City guides',$guides],['questions','question','Questions',$questions],['answers','answer','Answers',$answers],['recommendations','recommendation','Recommendations',$recommendations]] as [$key,$type,$title,$rows]): ?><section class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">COMMUNITY MODERATION</span><h2><?= h($title) ?></h2></div></div><?php if($rows): ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Submission</th><th>Contributor</th><th>Date</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php if($type==='photo'): ?><img class="admin-thumb" src="<?= app_path($r['image_path']) ?>" alt=""><strong><?= h($r['listing_name']) ?></strong><small><?= h($r['caption']) ?></small><?php elseif($type==='guide'): ?><strong><?= h($r['title']) ?></strong><small><?= h(text_excerpt($r['description'],140)) ?></small><?php elseif($type==='question'): ?><strong><?= h($r['title']) ?></strong><small><?= h($r['listing_name']) ?> · <?= h(text_excerpt($r['body'],120)) ?></small><?php elseif($type==='answer'): ?><strong><?= h($r['question_title']) ?></strong><small><?= h(text_excerpt($r['body'],150)) ?></small><?php else: ?><strong><?= h($r['listing_name']) ?></strong><small><?= h(text_excerpt($r['note'],160)) ?></small><?php endif; ?></td><td><?= h($r['contributor']??$r['creator']??$r['asker']??'Unknown') ?></td><td><?= h(format_date($r['created_at'])) ?></td><td><div class="row-actions"><?php $approve=$type==='photo'?'approved':'published';foreach([$approve,'rejected'] as $st): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="type" value="<?= h($type) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="<?= h($st) ?>"><button class="table-action <?= $st==='rejected'?'danger-text':'' ?>"><?= ucfirst($st) ?></button></form><?php endforeach; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="empty-admin">No pending items.</p><?php endif; ?></section><?php endforeach; ?>
<section class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">TRUST & SAFETY</span><h2>Content reports</h2></div></div><?php if($reports): ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Report</th><th>Reported by</th><th>Details</th><th>State</th><th>Actions</th></tr></thead><tbody><?php foreach($reports as $r): ?><tr><td><?= h(ucfirst($r['content_type'])) ?> #<?= (int)$r['content_id'] ?><small><?= h($r['reason']) ?></small></td><td><?= h($r['reporter']??'Guest / deleted user') ?></td><td><?= h($r['details']) ?></td><td><?= h($r['status']) ?></td><td><div class="row-actions"><?php foreach(['reviewed','dismissed'] as $st): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="type" value="report"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="<?= $st ?>"><button class="table-action"><?= ucfirst($st) ?></button></form><?php endforeach; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="empty-admin">No content reports. Good!</p><?php endif; ?></section>
